import {buildSpokenSummary,detectVoiceIntent} from './voice-summary.js';
export function createVoiceHelp({document:doc,getContext,getLanguage,onMap,onDictate,workerFactory}){
 const win=doc.defaultView,$=id=>doc.getElementById(id);let worker,request=0,audioUrl,signature,recognition,recording=false;
 const localized=(ur,en)=>getLanguage()==='ur'?ur:en;
 function status(ur,en){$('voice-status').textContent=localized(ur,en)}
 function stop(){request++;if($('voice-audio').src){try{$('voice-audio').pause()}catch{}}$('voice-read').disabled=false;status('آواز روک دی گئی ہے۔ نیا خلاصہ اپنے موجودہ اعداد سے سنیں۔','Audio stopped. Request a fresh explanation for your current inputs.')}
 function reset(){stop();$('voice-playback').hidden=true;$('voice-audio').removeAttribute('src');if(audioUrl){win.URL.revokeObjectURL(audioUrl);audioUrl=null}$('voice-transcript').textContent=''}
 function ensureWorker(){if(worker)return worker;const make=workerFactory||((url)=>new win.Worker(url,{type:'module'}));worker=make(new URL('./speech-worker.js',import.meta.url));worker.onmessage=e=>{const data=e.data;if(data.id!==request)return;$('voice-read').disabled=false;if(data.error){status(`آواز نہیں بن سکی: ${data.error}۔ نیچے تحریری خلاصہ پڑھیں۔`,`Speech failed: ${data.error}. The written explanation remains available.`);return}if(audioUrl)win.URL.revokeObjectURL(audioUrl);audioUrl=win.URL.createObjectURL(new win.Blob([data.buffer],{type:'audio/wav'}));$('voice-audio').src=audioUrl;$('voice-download').href=audioUrl;$('voice-download').download=getLanguage()==='ur'?'fieldshift-urdu-summary.wav':'fieldshift-english-summary.wav';$('voice-playback').hidden=false;status('آواز تیار ہے۔ اگر خود نہ چلے تو پلے دبائیں۔ یہ آپ کے اندازوں کا حساب ہے، حتمی زرعی مشورہ نہیں۔','Explanation ready. Press Play if it does not start automatically. This explains your assumptions, not a validated agronomic prescription.');try{const play=$('voice-audio').play();play?.catch(()=>status('آواز تیار ہے۔ سننے کے لیے آڈیو کا پلے بٹن دبائیں۔','Explanation ready. Press the audio Play button to listen.'))}catch{}};worker.onerror=()=>{worker?.terminate?.();worker=null;$('voice-read').disabled=false;status('آواز کا انجن نہیں کھل سکا۔ نیچے خلاصہ پڑھیں یا دوبارہ کوشش کریں۔','The speech engine could not load. Read the explanation below or retry.')};return worker}
 function speak(topic='summary'){if(recording)recognition?.stop();const context=getContext(),text=buildSpokenSummary(context,topic,getLanguage());$('voice-transcript').textContent=text;$('voice-playback').hidden=true;if(topic==='map'){onMap?.();return}if(!context.valid){status('پہلے کھیت کی معلومات اور مقام کے ناسا اعداد درست کریں۔','First correct field inputs and retrieve NASA observations matching the location.');return}if(!win.Worker&&!workerFactory){status('یہ براؤزر مقامی آواز کے انجن کو نہیں چلا سکتا۔ تحریری خلاصہ نیچے دستیاب ہے۔','This browser cannot run the local speech worker. Read the explanation below.');return}try{const id=++request;$('voice-read').disabled=true;status('آواز تیار ہو رہی ہے۔ پہلی بار تقریباً 24 میگابائٹ کا انجن کھلتا ہے؛ متن کسی آواز بنانے والی سروس کو نہیں بھیجا جاتا۔','Preparing speech. First use loads about 24 MB; text is not sent to an inference service.');ensureWorker().postMessage({id,text,language:getLanguage(),rate:Number($('voice-speed').value)});signature=JSON.stringify(context)}catch(e){$('voice-read').disabled=false;status(`آواز نہیں بن سکی: ${e.message}۔ تحریری خلاصہ پڑھیں۔`,`Speech unavailable: ${e.message}. Read the written explanation.`)}}
 $('voice-read').onclick=()=>speak();$('voice-stop').onclick=stop;for(const button of doc.querySelectorAll('[data-voice-topic]'))button.onclick=()=>speak(button.dataset.voiceTopic);
 $('voice-question-form').onsubmit=e=>{e.preventDefault();const intent=detectVoiceIntent($('voice-question').value);if(!intent){status('پانی، خرچ، مقامی جانچ یا نقشے کے بارے میں مختصر سوال کریں۔ یہ کھلا زرعی چیٹ بوٹ نہیں۔','Ask a short question about water, costs, local checks or the map. This is a guided explanation, not an open-ended agronomy chatbot.');return}speak(intent)};
 $('voice-mic').onclick=()=>onDictate?.();$('voice-mic-note').textContent=localized('اردو بول کر لکھنے کے لیے اوپر کی سہولت استعمال کریں۔ تحریر کو استعمال سے پہلے درست اور منظور کریں۔','Use the Urdu dictation panel above. Review the transcript before applying it.');
 try{$('voice-speed').value=win.localStorage.getItem('fieldshift-speech-rate')||'145'}catch{}$('voice-speed').onchange=()=>{try{win.localStorage.setItem('fieldshift-speech-rate',$('voice-speed').value)}catch{}};
 return {stop,contextChanged(){if(signature&&signature!==JSON.stringify(getContext())){reset();signature=null}},languageChanged(){reset()},destroy(){request++;worker?.terminate?.();recognition?.abort?.();if(audioUrl)win.URL.revokeObjectURL(audioUrl)}};
}
